def compute(vars):
    assets = vars["v1"]
    liabilities = vars["v2"]
    value = assets - liabilities
    return {
        "value": value,
        "trace": {
            "trading_assets_excluding_derivatives": assets,
            "trading_liabilities_excluding_derivatives": liabilities,
            "net_trading_assets": value,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
